class Solution:
    def firstMatchingCharacter(self, s: str) -> int:
        n = len(s)
        for i in range(n):
            if s[i] == s[n - 1 - i]:
                return i
        return -1

c.cpp:
class Solution {
public:
    int firstMatchingCharacter(string s) {
        int n = s.size();
        for (int i = 0; i < n; i++)
            if (s[i] == s[n - 1 - i]) return i;
        return -1;
    }
};

c.java:
class Solution {
    public int firstMatchingCharacter(String s) {
        int n = s.length();
        for (int i = 0; i < n; i++)
            if (s.charAt(i) == s.charAt(n - 1 - i)) return i;
        return -1;
    }
}

